// ---------------------------------------------------------------------------
// STRIP MARKDOWN FENCES — defensive parsing of model output
// ---------------------------------------------------------------------------
function stripFences(text) {
  if (!text) return "";
  return text
    .replace(/^```(?:json)?\s*/i, "")
    .replace(/\s*```\s*$/i, "")
    .trim();
}

// ---------------------------------------------------------------------------
// CORE HANDLER
// ---------------------------------------------------------------------------
exports.handler = async (event, context) => {
  // -- tier guard: YELLOW tier per AGENT-OPERATING-MODEL.md --
  // Per Sprint 3 Patch F validation; wraps the handler body.
  agentGuard("YELLOW", "selftest-sprint3-r3-2026-05-05");

  // -- query-param fast/slow path split (defensive pattern) --
  // ?refine=1 runs the full Claude call + KRITE pre-score.
  // Default (no ?refine=1) returns a fast-ack with status ok immediately.
  const params = (event && event.queryStringParameters) || {};
  const isRefine = params.refine === "1";

  // Shared response headers
  const headers = {
    "content-type": "application/json",
    "access-control-allow-origin": "*",
  };

  // -- FAST PATH — sub-200ms acknowledgement --
  if (!isRefine) {
    const fastResult = {
      status: "ok",
      path: "fast-ack",
      agent: "selftest-sprint3-r3-2026-05-05",
      marc_facing_summary:
        "Self-test acknowledged. The agent is running and reachable. " +
        "Add ?refine=1 to run the full Claude verification with KRITE pre-scoring.",
      doctrine_loaded: Object.keys(DOCTRINE),
      knowledge_tier: "T1",
      wku_check: {
        wisdom:
          "Fast-ack is the right call here — voice inbound safety pattern prevents timeout.",
        knowledge:
          "T1: Anthropic Building Effective Agents Dec 2024 — orchestrator-worker two-step pattern.",
        understanding:
          "Marc's fleet needs a self-test that can prove pipeline health without blocking on LLM latency.",
      },
    };

    return {
      statusCode: 200,
      headers,
      body: JSON.stringify(fastResult),
    };
  }

  // -- REFINE PATH — full Claude invocation + KRITE pre-score --
  // Only reached when ?refine=1 is present.

  let ANTHROPIC_API_KEY;
  try {
    ANTHROPIC_API_KEY = requireEnv("ANTHROPIC_API_KEY");
  } catch (err) {
    return {
      statusCode: 500,
      headers,
      body: JSON.stringify({
        error: "Missing required secret ANTHROPIC_API_KEY.",
        detail: err.message,
      }),
    };
  }

  // Build the user message for the self-test verification call.
  // Per rule_model_selection.md — claude-sonnet-4-6 for fast deterministic generation tasks.
  // (This is a fast generation / verification task, not a judgment/scoring task.)
  const userMessage = `
Sprint 3 Repair v3 self-test is running.

Context (T1 doctrine loaded at cold start):
${Object.entries(DOCTRINE)
  .map(([k, v]) => `- ${k}: ${v ? `${v.slice(0, 200)}...` : "(not found on this host)"}`)
  .join("\n")}

Task:
1. Confirm the Anthropic orchestrator-worker pattern is operational (T1 source: anthropic.com/research/building-effective-agents, Dec 2024).
2. Confirm the Wallace 2024 Instruction Hierarchy (T1: arxiv 2404.13208) is respected — agent respects system prompt over user overrides.
3. Apply the WKU three-pillar check to this self-test output.
4. Return a JSON object matching the OUTPUT FORMAT in your system prompt.
5. Apply SELF-DOUBT AS FEATURE: ask what could falsify the "ok" claim, then answer it.

Return ONLY valid JSON. No markdown fences. No extra prose outside the JSON.
`.trim();

  let claudeRawText = "";
  let claudeParsed = null;
  let traceId = null;

  try {
    // per rule_model_selection.md — Sonnet 4.6 for fast deterministic generation, never Haiku
    const traceResult = await tracedAnthropicCall({
      traceName: "selftest-sprint3-r3-2026-05-05.refine-verify",
      model: "claude-sonnet-4-6",
      maxTokens: 1024,
      system: SYSTEM_PROMPT,
      messages: [{ role: "user", content: userMessage }],
