        model: "claude-sonnet-4-6",
        stage: "refine-verify",
        agent: "selftest-sprint3-r3-2026-05-05",
        doctrine_keys: Object.keys(DOCTRINE),
      },
      apiKey: ANTHROPIC_API_KEY,
    });

    // Defensive extraction of content[0].text
    claudeRawText =
      traceResult &&
      traceResult.content &&
      Array.isArray(traceResult.content) &&
      traceResult.content[0] &&
      traceResult.content[0].text
        ? traceResult.content[0].text
        : "";

    traceId = (traceResult && traceResult._langfuseTraceId) || null;

    // Strip markdown fences before JSON parse
    const cleaned = stripFences(claudeRawText);

    try {
      claudeParsed = JSON.parse(cleaned);
    } catch (parseErr) {
      // Model returned non-JSON — treat as INCOMPLETE per anti-drift rules
      claudeParsed = {
        status: "INCOMPLETE",
        marc_facing_summary:
          "The verification call returned a response that could not be parsed as JSON. " +
          "This is flagged as INCOMPLETE per the EVIDENCE-OR-INCOMPLETE RULE — no faked completion.",
        raw_excerpt: claudeRawText.slice(0, 400),
        parse_error: parseErr.message,
      };
    }
  } catch (claudeErr) {
    return {
      statusCode: 502,
      headers,
      body: JSON.stringify({
        error: "Claude API call failed.",
        detail: claudeErr.message,
        agent: "selftest-sprint3-r3-2026-05-05",
      }),
    };
  }

  // -- KRITE pre-score of the Claude artifact --
