  let kriteResult = null;
  try {
    kriteResult = await kritiqueWithKrite({
      artifact: JSON.stringify(claudeParsed),
      agentName: "selftest-sprint3-r3-2026-05-05",
      context: {
        doctrine_loaded: Object.keys(DOCTRINE),
        model: "claude-sonnet-4-6",
        stage: "refine-verify",
      },
    });
  } catch (kriteErr) {
    // KRITE failure is non-fatal for a self-test — log the gap but do not suppress the result.
    kriteResult = {
      error: "KRITE pre-score unavailable in this environment.",
      detail: kriteErr.message,
      axes: null,
    };
  }

  // -- Build the final response --
  // Merge Claude's output with KRITE scores and evidence.
  // Per feedback_communication_style.md — marc_facing_summary leads in plain English.
  const finalStatus =
    claudeParsed && claudeParsed.status === "ok" ? "ok" : "INCOMPLETE";

  const response = {
    status: finalStatus,
    agent: "selftest-sprint3-r3-2026-05-05",
    sprint: "Sprint 3 Repair v3",
    marc_facing_summary:
      finalStatus === "ok"
        ? "The self-test ran the full verification path. Claude confirmed the orchestrator-worker " +
          "pipeline is operational, the anti-drift rules are embedded in the system prompt, " +
