      build_manual: "BUILD-AGENT-OPERATING-MANUAL-v1.md — Step 5 test-fire with evidence",
    },
    research_basis: {
      orchestrator_worker:
        "T1: anthropic.com/research/building-effective-agents (Anthropic Building Effective Agents, Dec 2024)",
      instruction_hierarchy:
        "T1: arxiv.org/abs/2404.13208 — Wallace 2024 Instruction Hierarchy",
    },
    agent_guard_tier: "YELLOW",
    knowledge_tier: "T1",
  };

  return {
    statusCode: 200,
    headers,
    body: JSON.stringify(response),
  };
};
